def s5():
    print("\n=== cross-type same-shape corr (L9), cross-layer corr, SVD/MP ===")
    def cos(a,b):
        a=a.ravel(); b=b.ravel()
        return float((a@b)/(np.linalg.norm(a)*np.linalg.norm(b)+1e-30))
    L9 = {t: find(9,t) for t in types}
    for i,t1 in enumerate(types):
        for t2 in types[i+1:]:
            if L9[t1] and L9[t2] and A_[L9[t1][0]].shape == A_[L9[t2][0]].shape:
                print(f"  cos({t1},{t2}) = {cos(B_[L9[t1][0]]-A_[L9[t1][0]], B_[L9[t2][0]]-A_[L9[t2][0]]):+.4f}")
    for t in types:
        rs = sorted([r for r in rows if t in r['name']], key=lambda x: x['L'])
        if len(rs) < 18: continue
        D = np.stack([(B_[r['name']]-A_[r['name']]).ravel() for r in rs])
        D /= np.linalg.norm(D, axis=1, keepdims=True)
        C = D@D.T - np.eye(18)
        name = [r['name'] for r in rs if r['L']==9][0]
        d0 = B_[name]-A_[name]
        s = np.linalg.svd(d0, compute_uv=False)
        mp = d0.std()*(np.sqrt(d0.shape[0])+np.sqrt(d0.shape[1]))
        print(f"  {t:10s} xlayer|cos|={np.abs(C).mean():.4f} max={np.abs(C).max():.4f} s0/MP={s[0]/mp:.3f} sR/MP={s[-1]/mp:.4f}")

