# (b) per-tensor sigma fit via simulation root-find + validation
cA, cB = Checkpoint('A'), Checkpoint('B')
ks = sorted(cA.keys())
A_ = {k: np.asarray(cA.get(k), dtype=np.float32) for k in ks}
B_ = {k: np.asarray(cB.get(k), dtype=np.float32) for k in ks}
def to_bf16(x):
    u = np.asarray(x, dtype=np.float32).view(np.uint32)
    return ((u + 0x7FFF + ((u >> 16) & 1)) & 0xFFFF0000).astype(np.uint32).view(np.float32)
def ulp16(x):
    return np.ldexp(1.0, np.frexp(np.abs(x))[1] - 8).astype(np.float32)
def lay(k):
    m = re.match(r'model\.layers\.(\d+)\.', k)
    return int(m.group(1)) if m else -1

def fit_sig(a, d, noise='lap'):
    u2 = (ulp16(a)*0.5).astype(np.float32)
    P0obs = float((d == 0).mean())
    rng = np.random.default_rng(101)
    if noise == 'lap':
        E = rng.standard_exponential(a.shape).astype(np.float32)
        E = (rng.integers(0, 2, a.shape) * 2 - 1) * E
    else:
        E = rng.standard_normal(a.shape).astype(np.float32)
    lo, hi = 1e-6, 3e-3
    for _ in range(28):
        mid = 0.5*(lo+hi)
        if (np.abs(mid*E) < u2).mean() > P0obs: lo = mid   # too small -> raise sigma
        else: hi = mid
    return 0.5*(lo+hi)

def stats(a, b):
    d = b - a; u = ulp16(a); nz = (np.abs(d)/u)[d != 0]
    rr = np.sqrt((d*d).mean(axis=1)); cc = np.sqrt((d*d).mean(axis=0))
    s = np.linalg.svd(d, compute_uv=False)
    mp = d.std()*(np.sqrt(d.shape[0])+np.sqrt(d.shape[1]))
    return (float((d==0).mean()), float(np.abs(d).mean()), float(np.median(nz)) if nz.size else 0,
            float((d**4).mean()/max(d.var()**2,1e-30)-3), float(rr.std()/rr.mean()), float(cc.std()/cc.mean()),
            float(s[0]/mp), float(s[1]/mp))

types = ['q_proj','k_proj','v_proj','o_proj','gate_proj','up_proj','down_proj']
TW = [t+'.weight' for t in types]
