    print("\n=== per-tensor sigma fit (Laplace vs Gauss) ===")
    print(f"{'type':10s} {'lam*1e4 mean+-std':>20s} {'sig*1e4 mean+-std':>20s}")
    fit_rows = []
    for t,tt in zip(types,TW):
        lam_l, lam_g = [], []
        for i, k in enumerate([k for k in ks if k.endswith(tt)]):
            d = B_[k]-A_[k]
            lam_l.append(fit_sig(A_[k], d, 'lap'))
            lam_g.append(fit_sig(A_[k], d, 'gau'))
        fit_rows.append((t, np.mean(lam_l), np.std(lam_l), np.mean(lam_g), np.std(lam_g)))
        print(f"{t:10s} {np.mean(lam_l)*1e4:9.3f} +- {np.std(lam_l)*1e4:5.3f}   {np.mean(lam_g)*1e4:11.3f} +- {np.std(lam_g)*1e4:5.3f}")
except Exception: print(traceback.format_exc())

try:
    print("\n=== sim validation at fitted lambda (Laplace): obs/sim ratios ===")
    for t,tt in zip(types,TW):
        sel = [k for k in ks if k.endswith(tt)]
        R = {f: [] for f in ['mad','snz','exk','cvr','cvc','s0','s1','P0']}
        for k in sel:
            a,b = A_[k],B_[k]; d = b-a
            lam = fit_sig(a, d, 'lap')
            rng = np.random.default_rng(99 + lay(k))
            E = rng.standard_exponential(a.shape).astype(np.float32)
            E = (rng.integers(0,2,a.shape)*2-1)*E
            bs = to_bf16(a + lam*E)
            so, ss = stats(a,b), stats(a,bs)
            for i,f in enumerate(['P0','mad','snz','exk','cvr','cvc','s0','s1']):
                R[f].append(so[i]/ss[i] if abs(ss[i]) > 1e-12 else 1.0)
        g = lambda f: np.mean(R[f])
        print(f"{t:10s} P0={g('P0'):.3f} mad={g('mad'):.3f} snzmed={g('snz'):.3f} exk={g('exk'):.3f} "
              f"cvr={g('cvr'):.3f} cvc={g('cvc'):.3f} s0/MP={g('s0'):.3f} s1/MP={g('s1'):.3f}")
except Exception: print(traceback.format_exc())

try:
